function validate(input) {
  const [actions, values] = input;
  const operations = ['add', 'subtract', 'multiply', 'divide', 'power'];
  if (!Array.isArray(actions) || actions.length < 2 || actions.length > 20000) return 'Give 2 to 20,000 actions.';
  if (!Array.isArray(values) || values.length !== actions.length - 1) return 'values needs one number for every action except "getResult".';
  if (actions[0] !== 'Calculator' || actions[actions.length - 1] !== 'getResult') return 'Start with "Calculator" and end with "getResult".';
  for (let i = 1; i < actions.length - 1; i++) {
    if (!operations.includes(actions[i])) return 'The actions in between must be add, subtract, multiply, divide or power.';
  }
  if (!values.every(value => typeof value === 'number' && Number.isFinite(value))) return 'Every value must be a finite number.';
  // Follow the chain: it must stay finite until it ends or divides by zero.
  let result = values[0];
  for (let i = 1; i < actions.length - 1; i++) {
    const value = values[i];
    if (actions[i] === 'divide' && value === 0) return null;
    if (actions[i] === 'add') result += value;
    else if (actions[i] === 'subtract') result -= value;
    else if (actions[i] === 'multiply') result *= value;
    else if (actions[i] === 'divide') result /= value;
    else result = Math.pow(result, value);
    if (!Number.isFinite(result)) return 'Keep every result along the chain a finite number (no overflow, no NaN).';
  }
  return null;
}

