function adapt(input, solve, kit) {
  const [actions, values] = input;
  let calculator = null;
  for (let i = 0; i < actions.length; i++) {
    const action = actions[i], value = values[i];
    const label = i === 0 ? `new Calculator(${value})` : action === 'getResult' ? 'getResult()' : `${action}(${value})`;
    if (i > 0 && (calculator === null || (typeof calculator !== 'object' && typeof calculator !== 'function') || typeof calculator[action] !== 'function')) {
      throw new Error(`The chain cannot call ${action}: every operation must return the calculator itself.`);
    }
    let returned;
    try {
      returned = i === 0 ? new solve(value) : action === 'getResult' ? calculator.getResult() : calculator[action](value);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      kit.trace(`${label} throws "${message}"`);
      return message;
    }
    if (action === 'getResult') {
      if (typeof returned !== 'number') throw new Error('getResult must return a number.');
      kit.trace(`getResult() returns ${returned}`);
      return returned;
    }
    kit.trace(`${label} is called`);
    calculator = returned;
  }
  throw new Error('The case has no "getResult" action.');
}

