function Calculator(value) {
  // Immutable version: every operation builds a fresh calculator around the new result.
  const make = current => ({
    add: x => make(current + x),
    subtract: x => make(current - x),
    multiply: x => make(current * x),
    divide: x => {
      if (x === 0) throw new Error('Division by zero is not allowed');
      return make(current / x);
    },
    power: x => make(Math.pow(current, x)),
    getResult: () => current,
  });
  return make(value);
}

