function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const apply = (action, result, value) => {
    if (action === 'add') return result + value;
    if (action === 'subtract') return result - value;
    if (action === 'multiply') return result * value;
    if (action === 'divide') return result / value;
    return Math.pow(result, value);
  };
  const choose = action => {
    if (action === 'add' || action === 'subtract') return rand() < 0.2 ? pick([0.5, 1.25, -2.5]) : int(-50, 50);
    if (action === 'multiply') return rand() < 0.2 ? pick([0.5, -1.5, 0]) : int(-5, 5);
    if (action === 'divide') return pick([1, 2, -2, 3, 4, -5, 8, 0.5, 10]);
    return pick([0, 1, 2, 2, 3, -1, 0.5]);
  };
  const count = small ? int(0, 6) : int(1500, 1998);
  // At most one division by zero, somewhere in the chain.
  const crash = rand() < (small ? 0.2 : 0.1) ? int(0, count - 1) : -1;
  let result = small ? int(-10, 10) : int(-100, 100);
  const actions = ['Calculator'], values = [result];
  for (let i = 0; i < count; i++) {
    if (i === crash) {
      actions.push('divide');
      values.push(0);
      continue;
    }
    let action = 'divide', value = 1000, next = result / 1000;
    // Retry until the result stays finite and of a moderate size; dividing by 1000 always shrinks it.
    for (let attempt = 0; attempt < 10; attempt++) {
      const candidate = pick(['add', 'subtract', 'multiply', 'divide', 'power']);
      const amount = choose(candidate), outcome = apply(candidate, result, amount);
      if (Number.isFinite(outcome) && Math.abs(outcome) <= 1e9) {
        action = candidate;
        value = amount;
        next = outcome;
        break;
      }
    }
    actions.push(action);
    values.push(value);
    result = next;
  }
  actions.push('getResult');
  return [actions, values];
}
